package com.codeguardian.config; import cn.dev33.satoken.interceptor.SaInterceptor; import cn.dev33.satoken.router.SaRouter; import cn.dev33.satoken.stp.StpUtil; import org.springframework.context.annotation.Configuration; import org.springframework.web.servlet.config.annotation.*; @Configuration public class SaTokenConfig implements WebMvcConfigurer{public void addInterceptors(InterceptorRegistry r){r.addInterceptor(new SaInterceptor(h->{SaRouter.match("/admin/**").check(x->StpUtil.checkLogin());SaRouter.match("/api/**").notMatch("/api/auth/**").check(x->StpUtil.checkLogin());SaRouter.match("/review/**").check(x->StpUtil.checkLogin());})).addPathPatterns("/**").excludePathPatterns("/auth/**","/api/auth/**","/css/**","/js/**","/images/**","/actuator/**","/error");}}
